  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #FAFAFA;
      --surface: #FFFFFF;
      --text: #171717;
      --text-secondary: #525252;
      --text-muted: #737373;
      --accent: #0072F5;
      --accent-hover: #0060D0;
      --border: #E5E5E5;
      --border-light: #F0F0F0;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.10);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 14px;
      --max-width: 1280px;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    }

    html { font-size: 16px; scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--text);
      background: var(--bg);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    /* ── Header ── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
    }
    .header-inner {
      max-width: var(--max-width); margin: 0 auto;
      display: flex; align-items: center; gap: 28px;
      padding: 0 32px; height: 58px;
    }
    .logo {
      font-size: 1.15rem; font-weight: 700; color: var(--text);
      text-decoration: none; white-space: nowrap; letter-spacing: -0.01em;
      display: flex; align-items: center; gap: 6px;
    }
    .logo svg { width: 24px; height: 24px; }
    .nav { display: flex; align-items: center; gap: 4px; flex: 1; }
    .nav-link {
      padding: 8px 14px; font-size: 0.875rem; font-weight: 500;
      color: var(--text-secondary); text-decoration: none; border-radius: var(--radius-sm);
      transition: color 0.15s, background 0.15s; cursor: pointer; white-space: nowrap;
      position: relative;
    }
    .nav-link:hover, .nav-link.active { color: var(--text); background: #F5F5F5; }
    .nav-link.has-dropdown::after {
      content: ''; display: inline-block; width: 0; height: 0;
      border-left: 4px solid transparent; border-right: 4px solid transparent;
      border-top: 4px solid currentColor; margin-left: 6px; vertical-align: middle;
      transition: transform 0.2s;
    }
    .nav-link.has-dropdown.open::after { transform: rotate(180deg); }

    .header-right {
      display: flex; align-items: center; gap: 8px; margin-left: auto;
    }
    .btn-ask {
      padding: 6px 14px; font-size: 0.8125rem; font-weight: 500;
      color: var(--text-secondary); background: var(--border-light);
      border: none; border-radius: var(--radius-sm); cursor: pointer;
      transition: background 0.15s; font-family: var(--font);
    }
    .btn-ask:hover { background: #E5E5E5; }
    .btn-login {
      padding: 6px 14px; font-size: 0.8125rem; font-weight: 500;
      color: var(--text); text-decoration: none; border-radius: var(--radius-sm);
      transition: background 0.15s;
    }
    .btn-login:hover { background: #F5F5F5; }
    .btn-signup {
      padding: 7px 18px; font-size: 0.8125rem; font-weight: 600;
      color: #FFF; background: var(--text); border: none;
      border-radius: var(--radius-sm); cursor: pointer;
      transition: background 0.15s; font-family: var(--font); white-space: nowrap;
    }
    .btn-signup:hover { background: #333; }

    /* ── Mega Menu ── */
    .mega-menu {
      position: absolute; top: 58px; left: 0; right: 0;
      background: var(--surface); border-bottom: 1px solid var(--border);
      box-shadow: var(--shadow-lg); padding: 32px 32px 40px;
      display: none; opacity: 0; transform: translateY(-4px);
      transition: opacity 0.2s, transform 0.2s;
    }
    .mega-menu.open { display: block; opacity: 1; transform: translateY(0); }
    .mega-menu-inner {
      max-width: var(--max-width); margin: 0 auto;
      display: flex; gap: 48px;
    }
    .mega-col { flex: 1; min-width: 0; }
    .mega-col-title {
      font-size: 0.6875rem; font-weight: 600; text-transform: uppercase;
      letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 14px;
    }
    .mega-item {
      display: flex; flex-direction: column; padding: 8px 10px; margin: 0 -10px;
      border-radius: var(--radius-sm); text-decoration: none; color: var(--text);
      transition: background 0.15s; margin-bottom: 4px;
    }
    .mega-item:hover { background: #F5F5F5; }
    .mega-item-name { font-size: 0.875rem; font-weight: 600; }
    .mega-item-desc { font-size: 0.75rem; color: var(--text-muted); margin-top: 1px; }

    /* ── Dropdown backdrop ── */
    .dropdown-backdrop {
      position: fixed; inset: 0; top: 58px; z-index: 99;
      background: rgba(0,0,0,0.2); display: none;
    }
    .dropdown-backdrop.open { display: block; }

    /* ── Page Shell ── */
    .page { max-width: var(--max-width); margin: 0 auto; padding: 0 32px; }

    /* ── Filters + Search ── */
    .filters-section {
      padding: 36px 0 20px;
    }
    .filters-row {
      display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
    }
    .pill {
      padding: 7px 16px; font-size: 0.8rem; font-weight: 500;
      border: 1px solid var(--border); background: var(--surface);
      color: var(--text-secondary); border-radius: 100px; cursor: pointer;
      transition: all 0.15s; font-family: var(--font); white-space: nowrap;
    }
    .pill:hover { border-color: #CCC; color: var(--text); }
    .pill.active {
      background: var(--text); color: #FFF; border-color: var(--text);
    }
    .search-wrap {
      margin-left: auto; position: relative;
    }
    .search-input {
      padding: 8px 14px 8px 34px; font-size: 0.825rem;
      border: 1px solid var(--border); border-radius: 100px;
      background: var(--surface); color: var(--text); outline: none;
      width: 220px; transition: border-color 0.15s, box-shadow 0.15s;
      font-family: var(--font);
    }
    .search-input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(0,114,245,0.12); }
    .search-input::placeholder { color: #999; }
    .search-icon {
      position: absolute; left: 12px; top: 50%; transform: translateY(-50%);
      color: var(--text-muted); pointer-events: none;
    }
    .search-icon svg { width: 15px; height: 15px; display: block; }

    /* ── Section Headers ── */
    .section-label {
      font-size: 0.6875rem; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--accent); margin-bottom: 8px;
    }
    .section-title {
      font-size: 1.75rem; font-weight: 700; letter-spacing: -0.02em;
      margin-bottom: 24px;
    }

    /* ── Featured Articles ── */
    .featured-section { padding: 0 0 48px; }
    .featured-grid {
      display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px;
    }
    .featured-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: box-shadow 0.25s, transform 0.25s;
      cursor: pointer; display: flex; flex-direction: column;
    }
    .featured-card:hover {
      box-shadow: var(--shadow-md); transform: translateY(-2px);
    }
    .featured-card-image {
      height: 180px; position: relative; overflow: hidden;
    }
    .featured-card-image .img-bg {
      position: absolute; inset: 0;
      background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    }
    .featured-card:nth-child(1) .img-bg {
      background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    }
    .featured-card:nth-child(2) .img-bg {
      background: linear-gradient(135deg, #0d1b2a 0%, #1b2838 50%, #1b3a4b 100%);
    }
    .featured-card:nth-child(3) .img-bg {
      background: linear-gradient(135deg, #1a1a2e 0%, #2d2d44 50%, #16213e 100%);
    }
    .img-pattern {
      position: absolute; inset: 0; opacity: 0.15;
      background-image:
        linear-gradient(45deg, rgba(255,255,255,0.05) 25%, transparent 25%),
        linear-gradient(-45deg, rgba(255,255,255,0.05) 25%, transparent 25%),
        linear-gradient(45deg, transparent 75%, rgba(255,255,255,0.05) 75%),
        linear-gradient(-45deg, transparent 75%, rgba(255,255,255,0.05) 75%);
      background-size: 20px 20px; background-position: 0 0, 0 10px, 10px -10px, -10px 0;
    }
    .featured-card-body { padding: 24px; flex: 1; display: flex; flex-direction: column; }
    .featured-card .card-category {
      display: inline-block; padding: 3px 10px; font-size: 0.6875rem; font-weight: 600;
      text-transform: uppercase; letter-spacing: 0.05em;
      background: rgba(0,114,245,0.08); color: var(--accent);
      border-radius: 100px; margin-bottom: 12px; width: fit-content;
    }
    .featured-card .card-date {
      font-size: 0.75rem; color: var(--text-muted); margin-bottom: 8px;
    }
    .featured-card h3 {
      font-size: 1.2rem; font-weight: 700; line-height: 1.35; letter-spacing: -0.01em;
      margin-bottom: 10px;
    }
    .featured-card p {
      font-size: 0.85rem; color: var(--text-secondary); line-height: 1.6;
      margin-bottom: 16px; flex: 1;
    }
    .featured-card .card-author {
      display: flex; align-items: center; gap: 10px; margin-top: auto;
    }
    .author-avatar {
      width: 28px; height: 28px; border-radius: 50%;
      background: var(--border); display: flex; align-items: center;
      justify-content: center; font-size: 0.7rem; font-weight: 700;
      color: var(--text-muted); flex-shrink: 0;
    }
    .author-name { font-size: 0.8125rem; font-weight: 500; color: var(--text); }

    /* Stats block inside featured card */
    .stats-block {
      display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
      margin: 16px 0; padding: 14px 16px;
      background: #F8FAFB; border-radius: var(--radius-md);
      border: 1px solid var(--border-light);
    }
    .stat-item { text-align: center; }
    .stat-value {
      font-size: 1.1rem; font-weight: 700; color: var(--accent);
      letter-spacing: -0.02em;
    }
    .stat-label {
      font-size: 0.65rem; color: var(--text-muted);
      text-transform: uppercase; letter-spacing: 0.04em;
      line-height: 1.3; margin-top: 2px;
    }

    /* ── Latest News ── */
    .news-section { padding: 0 0 48px; }
    .news-grid {
      display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px;
    }
    .news-card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius-md); overflow: hidden;
      transition: box-shadow 0.2s, transform 0.2s;
      cursor: pointer; display: flex; flex-direction: column;
    }
    .news-card:hover {
      box-shadow: var(--shadow-sm); transform: translateY(-1px);
    }
    .news-card:hover { border-color: #D0D0D0; }
    .news-card-body { padding: 22px; flex: 1; display: flex; flex-direction: column; }
    .news-card .card-category {
      display: inline-block; padding: 2px 9px; font-size: 0.65rem; font-weight: 600;
      text-transform: uppercase; letter-spacing: 0.05em;
      background: rgba(0,114,245,0.07); color: var(--accent);
      border-radius: 100px; margin-bottom: 10px; width: fit-content;
    }
    .news-card .card-date {
      font-size: 0.7rem; color: var(--text-muted); margin-bottom: 6px;
    }
    .news-card h3 {
      font-size: 1rem; font-weight: 600; line-height: 1.4; letter-spacing: -0.01em;
      margin-bottom: 8px;
    }
    .news-card p {
      font-size: 0.7875rem; color: var(--text-secondary); line-height: 1.55;
      margin-bottom: 14px; flex: 1;
    }
    .news-card .card-author {
      display: flex; align-items: center; gap: 8px;
    }
    .news-card .author-avatar { width: 24px; height: 24px; font-size: 0.625rem; }
    .news-card .author-name { font-size: 0.75rem; }

    /* ── No Results ── */
    .no-results {
      display: none; text-align: center; padding: 48px 0;
    }
    .no-results.visible { display: block; }
    .no-results-icon { font-size: 2.5rem; margin-bottom: 12px; opacity: 0.4; }
    .no-results h4 { font-size: 1.1rem; font-weight: 600; margin-bottom: 6px; }
    .no-results p { font-size: 0.85rem; color: var(--text-muted); }

    /* ── Show More ── */
    .show-more-wrap { text-align: center; padding: 8px 0 32px; }
    .btn-show-more {
      padding: 10px 28px; font-size: 0.85rem; font-weight: 600;
      color: var(--text); background: var(--surface);
      border: 1px solid var(--border); border-radius: var(--radius-sm);
      cursor: pointer; transition: all 0.15s; font-family: var(--font);
    }
    .btn-show-more.hidden { display: none; }
    .btn-show-more:hover { border-color: #CCC; background: #FAFAFA; }

    /* ── CTA Banner ── */
    .cta-section { padding: 0 0 64px; }
    .cta-banner {
      background: var(--text); color: #FFF; border-radius: var(--radius-lg);
      padding: 48px 52px; display: flex; align-items: center;
      gap: 40px; overflow: hidden; position: relative;
    }
    .cta-banner::before {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(0,114,245,0.15) 0%, transparent 60%);
      pointer-events: none;
    }
    .cta-content { flex: 1; position: relative; z-index: 1; }
    .cta-content h2 {
      font-size: 1.6rem; font-weight: 700; letter-spacing: -0.02em;
      line-height: 1.3; margin-bottom: 8px;
    }
    .cta-content p { font-size: 0.9rem; color: rgba(255,255,255,0.7); line-height: 1.55; }
    .cta-actions {
      display: flex; align-items: center; gap: 12px; flex-shrink: 0;
      position: relative; z-index: 1;
    }
    .btn-primary {
      padding: 12px 26px; font-size: 0.875rem; font-weight: 600;
      color: var(--text); background: #FFF; border: none;
      border-radius: var(--radius-sm); cursor: pointer;
      transition: background 0.15s; font-family: var(--font);
      white-space: nowrap;
    }
    .btn-primary:hover { background: #E8E8E8; }
    .btn-secondary {
      padding: 12px 26px; font-size: 0.875rem; font-weight: 600;
      color: #FFF; background: transparent; border: 1px solid rgba(255,255,255,0.3);
      border-radius: var(--radius-sm); cursor: pointer;
      transition: border-color 0.15s, background 0.15s;
      font-family: var(--font); white-space: nowrap;
    }
    .btn-secondary:hover { border-color: rgba(255,255,255,0.6); background: rgba(255,255,255,0.05); }

    /* Enterprise block */
    .enterprise-block {
      margin-top: 20px; padding: 28px 32px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: var(--radius-md);
    }
    .enterprise-block h3 {
      font-size: 1.05rem; font-weight: 700; margin-bottom: 6px;
    }
    .enterprise-block p {
      font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 14px;
    }
    .btn-enterprise {
      padding: 9px 20px; font-size: 0.8rem; font-weight: 600;
      color: #FFF; background: var(--accent); border: none;
      border-radius: var(--radius-sm); cursor: pointer;
      transition: background 0.15s; font-family: var(--font);
    }
    .btn-enterprise:hover { background: var(--accent-hover); }

    /* ── Footer ── */
    .footer {
      border-top: 1px solid var(--border); background: var(--surface);
      padding: 56px 32px 40px;
    }
    .footer-inner { max-width: var(--max-width); margin: 0 auto; }
    .footer-grid {
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
    }
    .footer-col { min-width: 0; }
    .footer-col-title {
      font-size: 0.6875rem; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 14px;
    }
    .footer-col a {
      display: block; font-size: 0.825rem; color: var(--text-secondary);
      text-decoration: none; padding: 3px 0; transition: color 0.15s;
      line-height: 1.7;
    }
    .footer-col a:hover { color: var(--text); }
    .footer-bottom {
      display: flex; align-items: center; justify-content: space-between;
      margin-top: 48px; padding-top: 24px; border-top: 1px solid var(--border-light);
      font-size: 0.75rem; color: var(--text-muted);
    }
    .footer-status { display: flex; align-items: center; gap: 7px; }
    .status-dot {
      width: 8px; height: 8px; border-radius: 50%; background: #22C55E;
      box-shadow: 0 0 0 3px rgba(34,197,94,0.2);
    }

    /* ── Responsive ── */
    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-card:last-child { grid-column: span 2; }
      .news-grid { grid-template-columns: 1fr 1fr; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
      .search-wrap { margin-left: 0; }
      .search-input { width: 180px; }
    }
    @media (max-width: 768px) {
      .header-inner { padding: 0 16px; gap: 12px; }
      .nav-link { font-size: 0.78rem; padding: 6px 8px; }
      .page { padding: 0 16px; }
      .featured-grid { grid-template-columns: 1fr; }
      .featured-card:last-child { grid-column: span 1; }
      .news-grid { grid-template-columns: 1fr; }
      .cta-banner { flex-direction: column; text-align: center; padding: 36px 28px; }
      .cta-actions { flex-direction: column; width: 100%; }
      .cta-actions .btn-primary,
      .cta-actions .btn-secondary { width: 100%; text-align: center; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .filters-row { gap: 6px; }
      .search-wrap { width: 100%; }
      .search-input { width: 100%; }
      .section-title { font-size: 1.4rem; }
      .featured-card h3 { font-size: 1.05rem; }
    }
    @media (max-width: 480px) {
      .header-inner { gap: 6px; overflow-x: auto; }
